/* ─── Vocabulary Bank ────────────────────────────────────────────────────── */
// Built from the teacher's own 25 units rather than hardcoded here. The old
// literal held three topics of generic single words — automation, digital,
// device — so a student met one vocabulary in the planner and a different,
// weaker one on the flashcard screen. Shape is unchanged so every screen that
// already reads this keeps working; only the source moved.
let VOCAB_BANK = {};
let _vocabBankReady = false;

// "Level" no longer means CEFR: these units are not graded that way. The real
// division in the data is what kind of item it is, and that is what the chips
// now offer.
const VOCAB_KINDS = ['all', 'colloc', 'verb'];

async function ensureVocabBank() {
  if (_vocabBankReady) return VOCAB_BANK;
  const units = await ensureVocabUnits();
  const bank = {};
  for (const u of units) {
    const colloc = (u.collocations || []).map(c => ({
      word: c.term,
      vietnamese: c.vi || '',
      definition: '',
      example: (u.samples || []).find(s => s.toLowerCase().includes(String(c.term).toLowerCase())) || '',
      collocations: [],
      kind: 'colloc',
    }));
    const verbs = (u.verbs || []).map(v => ({
      word: v.verb,
      vietnamese: v.vi || '',
      definition: v.with ? 'đi với ' + v.with : '',
      example: v.eg || '',
      collocations: v.with ? String(v.with).split(',').map(s => s.trim()).filter(Boolean) : [],
      kind: 'verb',
    }));
    bank[u.topic] = { all: [...colloc, ...verbs], colloc, verb: verbs };
  }
  VOCAB_BANK = bank;
  _vocabBankReady = true;
  return VOCAB_BANK;
}

