/* ─── Helpers ────────────────────────────────────────────────────────────── */
function show(id) { document.getElementById(id).classList.remove('hidden'); }
function hide(id) { document.getElementById(id).classList.add('hidden'); }

async function api(path, options = {}) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const res = await fetch(path, { ...options, headers: { ...headers, ...options.headers } });
  const data = await res.json();
  if (res.status === 401) {
    // Token expired or invalid — clear session and redirect to login
    token = null; currentUser = null;
    localStorage.removeItem('ielts_token');
    localStorage.removeItem('ielts_user');
    hide('app-screen');
    show('auth-screen');
    throw new Error('Session expired. Please sign in again.');
  }
  if (!res.ok) {
    // Carry the servers machine readable reason across, so a caller can tell a
    // transient failure from one that retrying will never fix.
    const err = new Error(data.error || 'Request failed');
    if (data.reason) err.reason = data.reason;
    err.status = res.status;
    throw err;
  }
  return data;
}

function bandColor(score) {
  if (!score) return '';
  if (score >= 8.5) return 'band-9';
  if (score >= 7.5) return 'band-8';
  if (score >= 6.5) return 'band-7';
  if (score >= 5.5) return 'band-6';
  if (score >= 4.5) return 'band-5';
  if (score >= 3.5) return 'band-4';
  return 'band-low';
}

function formatDate(dateStr) {
  return new Date(dateStr).toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

// Bài của học sinh không mất — chỉ phần chấm hỏng — nên câu chữ phải nói rõ
