function openGradingPanel(id) {
  const panel = document.getElementById(`grading-panel-${id}`);
  if (!panel) return;
  if (!panel.classList.contains('hidden') && panel.innerHTML) {
    panel.classList.add('hidden');
    panel.innerHTML = '';
    return;
  }

  // Build band score options (0 to 9 in 0.5 steps)
  const bandOptions = [];
  for (let v = 9; v >= 0; v -= 0.5) {
    bandOptions.push(`<option value="${v}">${v}</option>`);
  }
  const bandSel = bandOptions.join('');

  // Get essay text for annotation
  const queueItem = window._queueData && window._queueData[id];
  const essayText = queueItem ? (queueItem.essay || '') : '';
  const existingAnnotations = (queueItem && queueItem.annotations) ? queueItem.annotations : [];

  const annotationSection = essayText ? `
    <div class="annotation-section">
      <div class="annotation-section-header">
        <span style="font-weight:600;font-size:.9rem">📝 Inline Annotations</span>
        <span style="font-size:.78rem;color:var(--gray-500)">Select text in essay to annotate</span>
      </div>
      <div class="annotation-legend">
        <span class="ann-type grammar">Ngữ pháp</span>
        <span class="ann-type vocabulary">Từ vựng</span>
        <span class="ann-type argument">Lập luận</span>
        <span class="ann-type structure">Cấu trúc</span>
        <span class="ann-type strength">Điểm tốt</span>
      </div>
      <div class="annotatable-essay" id="annotatable-essay-${id}"></div>
    </div>` : '';

  panel.innerHTML = `
    <div class="grading-form">
      <h4>✏️ Manual Grading</h4>
      ${annotationSection}
      <div class="band-input-grid">
        <div class="band-input-row">
          <label>Task Achievement / Response</label>
          <select id="gp-ta-${id}" onchange="updateGradingOverall(${id})">${bandSel}</select>
        </div>
        <div class="band-input-row">
          <label>Coherence &amp; Cohesion</label>
          <select id="gp-cc-${id}" onchange="updateGradingOverall(${id})">${bandSel}</select>
        </div>
        <div class="band-input-row">
          <label>Lexical Resource</label>
          <select id="gp-lr-${id}" onchange="updateGradingOverall(${id})">${bandSel}</select>
        </div>
        <div class="band-input-row">
          <label>Grammatical Range &amp; Accuracy</label>
          <select id="gp-gra-${id}" onchange="updateGradingOverall(${id})">${bandSel}</select>
        </div>
      </div>
      <div class="overall-band-preview">
        Overall Band: <span class="overall-band-display" id="gp-overall-${id}">—</span>
      </div>
      <div class="form-group">
        <label>Feedback / Comments</label>
        <textarea id="gp-feedback-${id}" rows="5" placeholder="Write your feedback for the student here…"></textarea>
      </div>
      <div class="form-group">
        <label>Strengths (one per line)</label>
        <textarea id="gp-strengths-${id}" rows="3" placeholder="Good use of linking words&#10;Clear argument structure&#10;…"></textarea>
      </div>
      <div class="form-group">
        <label>Improvements (one per line)</label>
        <textarea id="gp-improvements-${id}" rows="3" placeholder="Vary sentence structures more&#10;Avoid repetition&#10;…"></textarea>
      </div>
      <div class="queue-actions" style="margin-top:4px;margin-bottom:4px">
        <button class="btn btn-outline btn-sm" id="gp-ai-btn-${id}" onclick="getAISuggest(${id})">🤖 AI Suggest Scores</button>
      </div>
      <div id="gp-ai-rationale-${id}" class="grading-ai-rationale hidden"></div>
      <div id="gp-error-${id}" class="error-msg hidden"></div>
      <div class="queue-actions" style="margin-top:8px">
        <button class="btn btn-primary" onclick="submitManualGrade(${id})">✅ Submit Grade</button>
        <button class="btn btn-outline" onclick="closeGradingPanel(${id})">Cancel</button>
      </div>
    </div>`;
  panel.classList.remove('hidden');
  updateGradingOverall(id);

  // Initialize annotation panel if essay available
  if (essayText) {
    if (!window._annotations) window._annotations = {};
    window._annotations[id] = existingAnnotations.slice();
    initAnnotationPanel(id, essayText, window._annotations[id]);
  }
}

async function getAISuggest(id) {
  const btn = document.getElementById(`gp-ai-btn-${id}`);
  const rationaleEl = document.getElementById(`gp-ai-rationale-${id}`);
  if (!btn || !rationaleEl) return;
  btn.disabled = true;
  btn.textContent = '⏳ Analyzing…';
  rationaleEl.classList.add('hidden');
  try {
    const result = await api(`/api/admin/submissions/${id}/ai-suggest`, { method: 'POST' });
    // Auto-fill the 4 band selects
    const setVal = (selId, val) => {
      const el = document.getElementById(selId);
      if (!el) return;
      // Find nearest available option
      const norm = Math.round(parseFloat(val) * 2) / 2;
      el.value = norm;
      if (!el.value) el.value = 6; // fallback
    };
    setVal(`gp-ta-${id}`,  result.task_achievement);
    setVal(`gp-cc-${id}`,  result.coherence_cohesion);
    setVal(`gp-lr-${id}`,  result.lexical_resource);
    setVal(`gp-gra-${id}`, result.grammatical_range);
    updateGradingOverall(id);
    if (result.rationale) {
      rationaleEl.textContent = '🤖 ' + result.rationale;
      rationaleEl.classList.remove('hidden');
    }
    btn.textContent = '🔄 Re-suggest';
  } catch (err) {
    rationaleEl.textContent = 'AI suggestion failed: ' + err.message;
    rationaleEl.classList.remove('hidden');
    btn.textContent = '🤖 AI Suggest Scores';
  }
  btn.disabled = false;
}

function closeGradingPanel(id) {
  const panel = document.getElementById(`grading-panel-${id}`);
  if (panel) { panel.classList.add('hidden'); panel.innerHTML = ''; }
}

function updateGradingOverall(id) {
  const ta  = parseFloat(document.getElementById(`gp-ta-${id}`)?.value  || 0);
  const cc  = parseFloat(document.getElementById(`gp-cc-${id}`)?.value  || 0);
  const lr  = parseFloat(document.getElementById(`gp-lr-${id}`)?.value  || 0);
  const gra = parseFloat(document.getElementById(`gp-gra-${id}`)?.value || 0);
  const overall = Math.round(((ta + cc + lr + gra) / 4) * 2) / 2;
  const el = document.getElementById(`gp-overall-${id}`);
  if (el) el.textContent = overall;
}

/* ─── Teacher Inline Essay Annotations ──────────────────────────────────── */

function initAnnotationPanel(subId, essayText, existingAnnotations) {
  const container = document.getElementById(`annotatable-essay-${subId}`);
  if (!container) return;
  renderAnnotatedEssay(container, essayText, existingAnnotations);
  container.addEventListener('mouseup', (e) => {
    const sel = window.getSelection();
    if (!sel || sel.isCollapsed || !sel.toString().trim()) return;
    // Compute offsets relative to plain-text essay
    const range = sel.getRangeAt(0);
    const preRange = document.createRange();
    preRange.selectNodeContents(container);
    preRange.setEnd(range.startContainer, range.startOffset);
    const start = preRange.toString().length;
    const selectedText = sel.toString();
    const end = start + selectedText.length;
    sel.removeAllRanges();
    showAnnotationPopup(subId, start, end, selectedText, e.clientX, e.clientY);
  });
}

const ANN_TYPE_LABELS = {
  grammar: 'Ngữ pháp', vocabulary: 'Từ vựng',
  structure: 'Cấu trúc', argument: 'Lập luận', strength: 'Điểm tốt',
};

// Essays graded before the structured fields existed packed everything into one
// string: 'Lỗi: <tên> → Sửa: "<câu đúng>" — <giải thích>'. Both shapes have to
// render, so old feedback stays readable instead of going blank.
function annParts(ann) {
  if (!ann) return { err: '', fix: '', why: '', up: '' };
  if (ann.err || ann.fix) {
    return { err: ann.err || '', fix: ann.fix || '', why: ann.why || '', up: ann.up || '' };
  }
  const c = (ann.comment || '').trim();
  if (!c) return { err: '', fix: '', why: '', up: '' };
  const m = c.match(/^L\u1ed7i:\s*(.+?)\s*\u2192\s*S\u1eeda:\s*["\u201c]?(.+?)["\u201d]?\s*(?:\u2014|-)\s*(.*)$/s);
  if (m) return { err: m[1].trim(), fix: m[2].trim(), why: (m[3] || '').trim(), up: '' };
  const g = c.match(/^\u0110i\u1ec3m t\u1ed1t:\s*(.*)$/s);
  if (g) return { err: 'Điểm tốt', fix: '', why: g[1].trim(), up: '' };
  return { err: '', fix: '', why: c, up: '' };
}

// One error, laid out so the student can act without reading a paragraph:
// what is wrong, the sentence they can paste straight back in, why, and what
// would lift that same sentence further.
function errorCardHtml(ann, i, opts = {}) {
  const p = annParts(ann);
  const type = ann.type || 'grammar';
  const original = ann.quote || opts.original || '';
  const isStrength = type === 'strength';
  const repeat = opts.repeatCount && opts.repeatCount > 1
    ? `<span class="ec-repeat" title="Ta đã mắc lỗi này ở ${opts.repeatCount} bài">🔁 lặp ×${opts.repeatCount}</span>` : '';
  return `
    <div class="err-card ec-${type}" data-ann-id="${ann.id || ''}" ${ann.id ? `onclick="jumpToAnnotation('${ann.id}')"` : ''}>
      <div class="ec-head">
        <span class="ec-num">${i + 1}</span>
        <span class="ec-type ann-type ${type}">${ANN_TYPE_LABELS[type] || type}</span>
        ${isStrength && (!p.err || p.err === ANN_TYPE_LABELS.strength) ? '' : `<span class="ec-err">${escHtml(p.err || 'Cần sửa')}</span>`}
        ${repeat}
      </div>
      ${original ? `<div class="ec-line ec-orig"><span class="ec-tag">${isStrength ? 'Trong bài' : 'Ta viết'}</span><span class="ec-text">${escHtml(original)}</span></div>` : ''}
      ${p.fix && !isStrength ? `<div class="ec-line ec-fix"><span class="ec-tag">Sửa thành</span><span class="ec-text">${escHtml(p.fix)}</span><button class="ec-copy" title="Chép câu đúng" data-fix="${escAttr(p.fix)}" onclick="event.stopPropagation();ecCopy(this)">⧉</button></div>` : ''}
      ${p.why ? `<div class="ec-why">${escHtml(p.why)}</div>` : ''}
      ${p.up ? `<div class="ec-up"><span class="ec-up-label">Muốn cao điểm hơn</span>${escHtml(p.up)}</div>` : ''}
      ${!isStrength && p.fix && opts.micro !== false ? `<button class="ec-micro" data-ec="${escAttr(JSON.stringify({ type, err: p.err, quote: original, fix: p.fix, why: p.why, up: p.up }))}" onclick="event.stopPropagation();makeMicroTask(this)">🎯 Luyện lỗi này</button>` : ''}
    </div>`;
}

// Escapes a value for an HTML *attribute*. It is NOT safe for building a JS
// string literal inside an onclick: the browser decodes &#39; back to an
// apostrophe before the JS is parsed, so any value containing one silently
// breaks the handler — the click throws a SyntaxError and nothing happens.
// Pass data through data-* attributes and read it off the element instead.
function escAttr(t) {
  return String(t).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/</g, '&lt;');
}

function ecCopy(btn) {
  const t = btn.dataset.fix || '';
  navigator.clipboard.writeText(t).then(() => {
    btn.textContent = '✓';
    setTimeout(() => { btn.textContent = '⧉'; }, 1200);
  }).catch(() => showToast('Không chép được'));
}

// Clicking a card scrolls the essay to the mark and flashes it, so the card and
// the sentence it is about are never more than one click apart.
function jumpToAnnotation(annId) {
  const mark = document.querySelector(`.ann-mark[data-ann-id="${annId}"]`);
  if (!mark) return;
  mark.scrollIntoView({ behavior: 'smooth', block: 'center' });
  mark.classList.add('ann-flash');
  setTimeout(() => mark.classList.remove('ann-flash'), 1600);
  document.querySelectorAll('.err-card.active').forEach(c => c.classList.remove('active'));
  const card = document.querySelector(`.err-card[data-ann-id="${annId}"]`);
  if (card) card.classList.add('active');
}

function ecFilter(type, btn) {
  document.querySelectorAll('.ec-filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  document.querySelectorAll('#err-panel-list .err-card').forEach(c => {
    c.classList.toggle('hidden', type !== 'all' && !c.classList.contains('ec-' + type));
  });
}

function renderAnnotatedEssay(container, essayText, annotations, readOnly = false) {
  if (!annotations || !annotations.length) {
    container.textContent = essayText;
    return;
  }
  // Sort by start offset
  const sorted = [...annotations].sort((a, b) => a.start_offset - b.start_offset);
  let html = '';
  let pos = 0;
  for (const ann of sorted) {
    if (ann.start_offset > pos) {
      html += escHtml(essayText.slice(pos, ann.start_offset));
    }
    const _p = annParts(ann);
    const safeComment = escHtml(ann.comment || [_p.err, _p.fix ? `→ "${_p.fix}"` : '', _p.why].filter(Boolean).join(' '));
    html += `<mark class="ann-mark ann-${ann.type}" data-ann-id="${ann.id}" data-comment="${safeComment}" data-type="${ann.type}">${escHtml(essayText.slice(ann.start_offset, ann.end_offset))}</mark>`;
    pos = ann.end_offset;
  }
  if (pos < essayText.length) {
    html += escHtml(essayText.slice(pos));
  }
  container.innerHTML = html;

  // Attach tooltip events
  container.querySelectorAll('.ann-mark').forEach(mark => {
    if (!readOnly) {
      mark.addEventListener('click', (e) => {
        e.stopPropagation();
        const annId = mark.dataset.annId;
        showAnnotationDeleteMenu(mark, annId);
      });
    }
    mark.addEventListener('mouseenter', (e) => showAnnTooltip(e, mark));
    mark.addEventListener('mouseleave', hideAnnTooltip);
  });
}

// What this student keeps getting wrong across every essay they have written.
// Counted from marks already stored on graded essays, so opening it costs
// nothing and it sharpens with each new submission.
/* ─── Micro tasks ─────────────────────────────────────────────────────────
   Reading a correction changes nothing on its own. A micro task takes one
   mistake the student actually made and gives them three fresh sentences with
   the same fault to fix, so they have to produce the right form rather than
   recognise it. Built once by the model and stored, so coming back is free. */

const MICRO_STATUS = {
  pending: ['Chưa luyện', 'st-pending'],
  learning: ['Đang luyện', 'st-learning'],
  done: ['Đã sửa được', 'st-done'],
};

async function makeMicroTask(btn) {
  // The payload rides on the element, not in the onclick — see escAttr.
  let d;
  try { d = JSON.parse(btn.dataset.ec || '{}'); } catch (e) { d = {}; }
  if (!d.quote || !d.fix) { showToast('Thẻ lỗi này thiếu dữ liệu để dựng bài luyện.'); return; }
  btn.disabled = true;
  const label = btn.textContent;
  btn.textContent = 'Đang dựng bài…';
  try {
    const r = await api('/api/micro-tasks', {
      method: 'POST',
      body: JSON.stringify({
        type: d.type, err: d.err, quote: d.quote,
        fix: d.fix, why: d.why, up: d.up,
      }),
    });
    btn.textContent = r.reused ? '✓ Đã có trong danh sách' : '✓ Đã thêm vào Luyện lỗi';
    btn.classList.add('added');
    showToast(r.reused ? 'Lỗi này đã có bài luyện rồi.' : 'Đã thêm. Vào "Luyện lỗi của tôi" để làm.');
  } catch (e) {
    btn.disabled = false;
    btn.textContent = label;
    showToast('Chưa dựng được: ' + e.message);
  }
}

let _microTasks = [];
let _microOpen = null;
let _microIdx = 0;
let _microRun = { right: 0, total: 0 };

/* ─── 14 trục lập luận ────────────────────────────────────────────────────
   The teacher's own material: 100 recent exam prompts collapsed onto 14
   reusable argument machines. A student who works through prompts one at a
   time never notices that three of them are the same argument; the axis is the
   unit that transfers. */

let _trucCache = null;
let _trucCurrent = null;

/* ─── Chuỗi lập luận, bài học trước khi viết ──────────────────────────────
   Every axis in the bank runs the same six links. Teaching them once, in one
   place, is cheaper than teaching them fourteen times inside the axes. The
   worked example and the gapped drill both come from the bank so the lesson
   and the axes never drift apart. */

