/* =====================================================
   TỪ VỰNG THEO BUỔI — flashcard and Bắn Chữ over LESSON_VOCAB
   One picker (one lesson, or several mixed), three ways to use the words.
   Bắn Chữ has two modes. "Nhìn tiếng Anh" shows the word and the student
   types it back; "Nhìn nghĩa Việt" hides the English, so the word has to come
   out of memory. Known words and best scores live in localStorage only.
   ===================================================== */
let _lvSrc = 'lesson';
const _lvSelBy = { lesson: new Set(), unit: new Set() };
let _lvFront = 'en';
let _lvSkipKnown = false;
// Which box of the 25 units: 'basic' (B1–B2) or 'adv' (C1 plus the original items).
let _lvTier = 'basic';
let _fc = null;
let _fcKeyHandler = null;

(function lvRestore() {
  try {
    const s = JSON.parse(localStorage.getItem('lvSel') || '[]');
    if (Array.isArray(s)) s.forEach(n => { if (LESSON_VOCAB.some(t => t.n === n)) _lvSelBy.lesson.add(n); });
    const u = JSON.parse(localStorage.getItem('lvSelUnit') || '[]');
    if (Array.isArray(u)) u.forEach(n => { if (Number.isInteger(n) && n >= 1 && n <= 40) _lvSelBy.unit.add(n); });
    _lvSrc = localStorage.getItem('lvSrc') === 'unit' ? 'unit' : 'lesson';
    _lvFront = localStorage.getItem('lvFront') === 'vi' ? 'vi' : 'en';
    _lvSkipKnown = localStorage.getItem('lvSkipKnown') === '1';
    _lvTier = localStorage.getItem('lvTier') === 'adv' ? 'adv' : 'basic';
  } catch (e) {}
})();

function lvSave(key, val) { try { localStorage.setItem(key, val); } catch (e) {} }

// "Nhớ rồi" marks belong to the account, not the browser. The server holds
// them with the student's Kiểm tra history; this is a cache of the signed-in
// student's copy, and changes go up in small batches.
let _lvProg = { uid: undefined, loaded: false, loading: null, known: new Set(), tests: [] };
let _lvPend = { add: new Set(), remove: new Set(), timer: null };
const lvCacheKey = () => 'lvKnown:' + (currentUser ? currentUser.id : '');
function lvProgFor() {
  const uid = currentUser ? currentUser.id : null;
  if (_lvProg.uid !== uid) {
    let cached = [];
    try { cached = JSON.parse(localStorage.getItem(lvCacheKey()) || '[]'); } catch (e) {}
    _lvProg = { uid, loaded: false, loading: null, known: new Set(cached), tests: [] };
    clearTimeout(_lvPend.timer);
    _lvPend = { add: new Set(), remove: new Set(), timer: null };
  }
  return _lvProg;
}
function lvKnownSet() { return new Set(lvProgFor().known); }
function lvSaveKnown(set) {
  const p = lvProgFor();
  set.forEach(w => { if (!p.known.has(w)) { _lvPend.add.add(w); _lvPend.remove.delete(w); } });
  p.known.forEach(w => { if (!set.has(w)) { _lvPend.remove.add(w); _lvPend.add.delete(w); } });
  p.known = new Set(set);
  lvSave(lvCacheKey(), JSON.stringify([...set]));
  clearTimeout(_lvPend.timer);
  _lvPend.timer = setTimeout(lvFlushKnown, 1500);
}
async function lvFlushKnown() {
  const add = [..._lvPend.add], remove = [..._lvPend.remove];
  if (!add.length && !remove.length) return;
  _lvPend.add = new Set();
  _lvPend.remove = new Set();
  try {
    await api('/api/vocab/progress/known', { method: 'POST', body: JSON.stringify({ add, remove }) });
  } catch (e) {
    // Offline or the server hiccuped: keep them and try again later.
    add.forEach(w => { if (!_lvPend.remove.has(w)) _lvPend.add.add(w); });
    remove.forEach(w => { if (!_lvPend.add.has(w)) _lvPend.remove.add(w); });
    clearTimeout(_lvPend.timer);
    _lvPend.timer = setTimeout(lvFlushKnown, 15000);
  }
}
window.addEventListener('pagehide', () => { lvFlushKnown(); });
function lvLoadProgress() {
  const p = lvProgFor();
  if (p.loaded) return Promise.resolve(p);
  if (p.loading) return p.loading;
  p.loading = api('/api/vocab/progress').then(r => {
    // Marks made in this browser before they were kept per account go to the
    // first account that opens the games here, once.
    let old = [];
    try { if (!localStorage.getItem('lvKnownMoved')) old = JSON.parse(localStorage.getItem('lvKnown') || '[]'); } catch (e) {}
    const set = new Set(r.known || []);
    old.forEach(w => { if (w && !set.has(w)) { set.add(w); _lvPend.add.add(w); } });
    _lvPend.add.forEach(w => set.add(w));
    _lvPend.remove.forEach(w => set.delete(w));
    p.known = set;
    p.tests = r.tests || [];
    p.loaded = true;
    lvSave(lvCacheKey(), JSON.stringify([...set]));
    try { localStorage.setItem('lvKnownMoved', '1'); localStorage.removeItem('lvKnown'); } catch (e) {}
    if (_lvPend.add.size || _lvPend.remove.size) lvFlushKnown();
    return p;
  }).catch(() => { p.loading = null; return p; });
  return p.loading;
}

function lvSel() { return _lvSelBy[_lvSrc]; }

// Two word sources behind one picker: the 12 lesson handouts (LESSON_VOCAB)
// and the 25 vocabulary units (VOCAB_BANK, fetched from the server).
function lvTopics(src = _lvSrc, tier = _lvTier) {
  if (src === 'unit') {
    return (_vocabUnits || []).map((u, i) => ({
      id: i + 1,
      label: 'Unit ' + (i + 1),
      title: u.topic,
      items: lvUnitItems(u, tier),
    }));
  }
  return LESSON_VOCAB.map(t => ({
    id: t.n,
    label: 'Buổi ' + t.n,
    title: t.title,
    items: t.groups.flatMap(g => g.items.map(([en, vi, use, ex]) => ({ en, vi, use, ex, group: g.name }))),
  }));
}

// One unit's cards in the chosen box. Cơ bản: B1 and B2 words and easy
// phrases. Nâng cao: C1 words, harder phrases (Strong and Precise in the
// teacher's handbook), then the unit's original collocations and verbs.
function lvUnitItems(u, tier = _lvTier) {
  const row = (group, lvl) => ([en, pos, vi, ex]) => ({ en, vi, use: [lvl, pos].filter(Boolean).join(' · '), ex: ex || '', group });
  if (tier === 'basic') {
    const b = u.basic || {};
    return [...(b.B1 || []).map(row('Từ B1', 'B1')), ...(b.B2 || []).map(row('Từ B2', 'B2')), ...(b.colloc || []).map(row('Cụm từ', 'B1–B2'))];
  }
  const adv = u.advanced || {};
  const old = ((VOCAB_BANK[u.topic] || {}).all || [])
    // Two Crime & Justice rows hold Vietnamese where the English verb should be.
    .filter(w => w.word && w.vietnamese && !/[^\x00-\x7F]/.test(w.word))
    .map(w => ({
      en: w.word,
      vi: w.vietnamese,
      use: w.kind === 'verb' && w.definition ? 'Hay ' + w.definition : '',
      ex: w.example || '',
      group: w.kind === 'verb' ? 'Động từ' : 'Cụm từ',
    }));
  return [...(adv.C1 || []).map(row('Từ C1', 'C1')), ...(adv.colloc || []).map(row('Cụm nâng cao', 'C1')), ...old];
}
function lvSetTier(t) {
  _lvTier = t === 'adv' ? 'adv' : 'basic';
  lvSave('lvTier', _lvTier);
  tsSfx('key');
  lvRenderHub();
}

// Words repeat across topics (erode appears in four lessons). When topics are
// mixed each word is kept once, under the first topic that has it.
function lvPool() {
  const sel = lvSel();
  const seen = new Set();
  const out = [];
  lvTopics().filter(t => !sel.size || sel.has(t.id)).forEach(t => t.items.forEach(w => {
    const k = w.en.toLowerCase();
    if (seen.has(k)) return;
    seen.add(k);
    out.push({ ...w, tag: t.label });
  }));
  return out;
}

function showLessonVocab() {
  tsStop();
  lvUnbindKeys();
  lvRenderHub();
}

function lvRenderHub() {
  const root = document.getElementById('lesson-vocab-root');
  if (!root) return;
  tsStop();
  lvUnbindKeys();
  if (_lvSrc === 'unit' && !_vocabBankReady) {
    root.innerHTML = '<div class="loading">Đang tải 25 unit…</div>';
    ensureVocabBank().then(() => { if (_vocabBankReady) lvRenderHub(); }).catch(e => {
      root.innerHTML = `<div class="lv-wrap"><button class="btn-back-plain" onclick="lvSetSrc('lesson')">← Về ${LESSON_VOCAB.length} buổi</button><div class="error-msg" style="display:block">${escHtml(e.message)}</div></div>`;
    });
    return;
  }
  const known = lvKnownSet();
  const topics = lvTopics();
  const sel = lvSel();
  const pool = lvPool();
  const unitWord = _lvSrc === 'unit' ? 'unit' : 'buổi';
  const selLabel = sel.size ? `${sel.size} ${unitWord}` : `cả ${topics.length} ${unitWord}`;
  const chips = topics.map(t => {
    const k = t.items.filter(i => known.has(i.en.toLowerCase())).length;
    return `<button class="lv-topic${sel.has(t.id) ? ' active' : ''}" onclick="lvToggle(${t.id})">
      <span class="lv-topic-n">${escapeHtml(t.label)}</span>
      <span class="lv-topic-name">${escapeHtml(t.title)}</span>
      <span class="lv-topic-known">${t.items.length ? `${k}/${t.items.length} đã nhớ` : 'đang soạn'}</span>
      ${t.items.length ? lvBar(k, t.items.length, true) : ''}
    </button>`;
  }).join('');
  const all = lvSetCount(topics, known);
  root.innerHTML = `
    <div class="lv-wrap">
      <button class="btn-back-plain" onclick="showView('games')">← Trò chơi</button>
      <div class="lv-head">
        <div class="vb-logo">📚 Flashcard và Bắn Chữ</div>
        <div class="lv-src">
          <button class="vb-chip${_lvSrc === 'lesson' ? ' active' : ''}" onclick="lvSetSrc('lesson')">${LESSON_VOCAB.length} buổi Writing Task 2</button>
          <button class="vb-chip${_lvSrc === 'unit' ? ' active' : ''}" onclick="lvSetSrc('unit')">25 unit từ vựng</button>
        </div>
        ${_lvSrc === 'unit' ? `<div class="lv-tier">
          <button class="lv-tier-btn lv-tier-btn--basic${_lvTier === 'basic' ? ' active' : ''}" onclick="lvSetTier('basic')">🌱 Cơ bản<small>B1–B2 · từ và cụm dễ</small></button>
          <button class="lv-tier-btn lv-tier-btn--adv${_lvTier === 'adv' ? ' active' : ''}" onclick="lvSetTier('adv')">🚀 Nâng cao<small>C1 · cụm học thuật</small></button>
        </div>` : ''}
        <div class="vb-tagline">Chọn một ${unitWord} để học riêng, hoặc chọn nhiều ${unitWord} để trộn. Không chọn ${unitWord} nào là trộn tất cả.</div>
      </div>
      <button class="lvp-hubbar" onclick="lvShowProgress()">
        <span class="lvp-hubbar-top"><strong>📊 Tiến độ ${_lvSrc === 'unit' ? (_lvTier === 'adv' ? '🚀 Nâng cao' : '🌱 Cơ bản') : LESSON_VOCAB.length + ' buổi'}</strong><span>${all.k}/${all.n} thẻ · ${lvPct(all.k, all.n)}%</span></span>
        ${lvBar(all.k, all.n)}
        <span class="lvp-hubbar-link">Xem tiến độ từng chủ đề và lịch sử kiểm tra →</span>
      </button>
      <div class="lv-topics">${chips}</div>
      <div class="lv-selbar">
        <span>Đang chọn <strong>${selLabel}</strong> · ${pool.length} từ</span>
        ${sel.size ? '<button class="lv-link" onclick="lvClearSel()">Bỏ chọn, trộn tất cả</button>' : ''}
      </div>
      <div class="quest-box" id="quest-box"></div>
      <div class="wal-bar" id="wal-bar"></div>
      <div class="wal-shop hidden" id="wal-shop"></div>
      <div class="lv-modes">
        <button class="lv-mode" onclick="lvStartFlash()">
          <span class="lv-mode-icon">🃏</span>
          <span class="lv-mode-name">Flashcard</span>
          <span class="lv-mode-desc">Lật thẻ xem nghĩa, cách dùng và câu mẫu. Tự đánh dấu nhớ hay chưa.</span>
        </button>
        <button class="lv-mode" onclick="qtSetup()">
          <span class="lv-mode-icon">📝</span>
          <span class="lv-mode-name">Kiểm tra</span>
          <span class="lv-mode-desc">Bài kiểm tra kiểu Quizlet trên các thẻ đã nhớ: đúng sai, trắc nghiệm, tự gõ, nối từ. Nộp một lần, xem ngay từ sai.</span>
          <span class="lv-mode-best">✓ ${lvKnownCount(pool)} thẻ đã nhớ</span>
        </button>
        <button class="lv-mode" onclick="tsStart('copy')">
          <span class="lv-mode-icon">🚀</span>
          <span class="lv-mode-name">Bắn chữ, nhìn tiếng Anh</span>
          <span class="lv-mode-desc">Từ tiếng Anh rơi xuống, gõ lại cho đúng để bắn. Hợp để khởi động.</span>
          <span class="lv-mode-best">🏆 ${tsGetBest('copy')}</span>
        </button>
        <button class="lv-mode" onclick="tsStart('meaning')">
          <span class="lv-mode-icon">🎯</span>
          <span class="lv-mode-name">Bắn chữ, nhìn nghĩa Việt</span>
          <span class="lv-mode-desc">Nghĩa tiếng Việt rơi xuống kèm chữ cái đầu. Gõ từ tiếng Anh để bắn.</span>
          <span class="lv-mode-best">🏆 ${tsGetBest('meaning')}</span>
        </button>
        <button class="lv-mode" onclick="tsStart('colloc')">
          <span class="lv-mode-icon">🧩</span>
          <span class="lv-mode-name">Bắn chữ, ghép cụm từ</span>
          <span class="lv-mode-desc">Cụm từ rơi xuống thiếu một từ chính. Gõ đúng từ còn thiếu để bắn. Luyện collocation cho Writing.</span>
          <span class="lv-mode-best">🏆 ${tsGetBest('colloc')}</span>
        </button>
        <button class="lv-mode" onclick="twStart()">
          <span class="lv-mode-icon">🏗️</span>
          <span class="lv-mode-name">Xây tháp</span>
          <span class="lv-mode-desc">Điền từ vào câu. Đúng thì xây thêm tầng, sai thì rơi tầng. Từ tầng 21 phải tự gõ đúng dạng. Phần đang chọn có ${twPool().length} câu.</span>
          <span class="lv-mode-best" id="tw-hub-best">🏆 ${twGetBest()} tầng</span>
          <span class="lv-mode-progress" id="tw-hub-progress"></span>
        </button>
        <button class="lv-mode lv-mode--raid" onclick="raidMap()">
          <span class="lv-mode-icon">⚔️</span>
          <span class="lv-mode-name">Chinh phạt hầm ngục</span>
          <span class="lv-mode-desc">Chọn nhân vật và cấp theo band, đánh theo lượt với quái và boss bằng từ vựng và văn mẫu của từng buổi. Chọn chém, hồi máu hay tuyệt kỹ, rồi gõ từ còn thiếu để ra đòn.</span>
        </button>
      </div>
    </div>`;
  twHubProgress();
  walBar();
  walLoad().then(walBar);
  questRenderBox();
  questLoad(true).then(questRenderBox);
  if (!lvProgFor().loaded) lvLoadProgress().then(p => { if (p.loaded && document.querySelector('#lesson-vocab-root .lv-topics')) lvRenderHub(); });
}

/* ─── Quay về và đổi chế độ, từ giữa bất kỳ game nào ─────────────────────── */
const LV_MODES = [
  { id: 'flash',   icon: '🃏', name: 'Flashcard' },
  { id: 'test',    icon: '📝', name: 'Kiểm tra' },
  { id: 'copy',    icon: '🚀', name: 'Bắn chữ, nhìn tiếng Anh' },
  { id: 'meaning', icon: '🎯', name: 'Bắn chữ, nhìn nghĩa Việt' },
  { id: 'colloc',  icon: '🧩', name: 'Bắn chữ, ghép cụm từ' },
  { id: 'tower',   icon: '🏗️', name: 'Xây tháp' },
  { id: 'raid',    icon: '⚔️', name: 'Chinh phạt hầm ngục' },
];

// Which game is on screen right now, if any.
function lvCurrentMode() {
  if (_rd) return 'raid';
  if (document.querySelector('#lesson-vocab-root .qt-wrap, #lesson-vocab-root .qt-setup')) return 'test';
  if (_ts) return _ts.mode;
  if (_tw && document.getElementById('tw-card')) return 'tower';
  if (document.querySelector('#lesson-vocab-root .lv-fc-top')) return 'flash';
  return null;
}

// Leaving mid-round keeps what was earned: coins go in, a Bắn Chữ score
// still counts for the record, and the tower is saved where it stands.
function tsBank(g) {
  if (!g || g.banked) return;
  g.banked = true;
  walEarn(g.coins, true);
  if (g.score > tsGetBest(g.mode, g.diffKey)) tsSetBest(g.mode, g.diffKey, g.score);
  if (g.score > 0) api('/api/game/score', { method: 'POST', body: JSON.stringify({ mode: g.mode, diff: g.diffKey, score: g.score }) }).catch(() => {});
}
function lvLeaveGame() {
  if (_ts) { const g = _ts; tsStop(); tsBank(g); }
  if (_tw && document.getElementById('tw-card')) {
    if (!_tw.collapsed && !_tw.revivable) twSave(_tw, true);
    walFlush();
  }
  twStop();
  lvUnbindKeys();
  document.getElementById('lv-modal')?.remove();
}
function lvBack() {
  lvLeaveGame();
  tsSfx('equip');
  lvRenderHub();
}
function lvOpenShop() {
  lvLeaveGame();
  tsSfx('equip');
  _walShopOpen = true;
  lvRenderHub();
  document.getElementById('wal-bar')?.scrollIntoView({ block: 'start', behavior: 'smooth' });
}
function lvSwitch(mode) {
  const list = _ts ? _ts.list : null;
  lvLeaveGame();
  tsSfx('equip');
  if (mode === 'flash') lvStartFlash();
  else if (mode === 'test') qtSetup();
  else if (mode === 'tower') twStart();
  else if (mode === 'raid') raidMap();
  else tsStart(mode, list);
}

// The switch menu: the four games, and the Bắn Chữ speed. A game in play is
// paused underneath and carries on if the menu is closed.
function lvModeModal() {
  const cur = lvCurrentMode();
  if (_ts && _ts.reviving) return;
  if (_ts && !_ts.paused) tsPause();
  document.getElementById('lv-modal')?.remove();
  const el = document.createElement('div');
  el.id = 'lv-modal';
  el.className = 'lv-modal';
  el.addEventListener('click', e => { if (e.target === el) lvModalClose(); });
  document.body.appendChild(el);
  lvModalRender(cur);
  tsSfx('key');
}
function lvModalRender(cur) {
  const el = document.getElementById('lv-modal');
  if (!el) return;
  const speedChanged = _ts && _ts.diffKey !== _tsDiff;
  el.innerHTML = `
    <div class="lv-modal-card">
      <div class="lv-modal-title">🔀 Đổi chế độ chơi</div>
      <div class="lv-modal-modes">${LV_MODES.map(m => {
        const here = m.id === cur;
        const again = here && speedChanged;
        return `<button class="lv-modal-mode${here ? ' here' : ''}" onclick="lvSwitch('${m.id}')" ${here && !again ? 'disabled' : ''}>
          <span class="lv-modal-icon">${m.icon}</span><span>${escapeHtml(m.name)}</span>
          ${here ? `<small>${again ? 'chơi lại với tốc độ mới' : 'đang chơi'}</small>` : ''}</button>`;
      }).join('')}</div>
      <div class="lv-modal-speed">
        <span>Tốc độ Bắn Chữ</span>
        ${Object.entries(TS_DIFFS).map(([k, d]) => `<button class="vb-chip${_tsDiff === k ? ' active' : ''}" onclick="lvModalSpeed('${k}')">${d.label}</button>`).join('')}
      </div>
      <div class="lv-modal-btns">
        ${cur ? '<button class="vb-start-btn" onclick="lvModalClose()">▶ Chơi tiếp</button>' : ''}
        <button class="vb-secondary-btn" onclick="lvOpenShop()">🛒 Cửa hàng</button>
        <button class="vb-secondary-btn" onclick="lvBack()">← Về chọn buổi</button>
      </div>
    </div>`;
}
function lvModalSpeed(k) {
  if (!TS_DIFFS[k]) return;
  _tsDiff = k;
  lvSave('tsDiff', k);
  tsSfx('key');
  lvModalRender(lvCurrentMode());
}
function lvModalClose() {
  document.getElementById('lv-modal')?.remove();
  if (_ts && _ts.paused && !_ts.reviving) tsResume();
}

function lvSetSrc(src) {
  _lvSrc = src === 'unit' ? 'unit' : 'lesson';
  lvSave('lvSrc', _lvSrc);
  lvRenderHub();
}
function lvSelKey() { return _lvSrc === 'unit' ? 'lvSelUnit' : 'lvSel'; }
function lvToggle(id) {
  const sel = lvSel();
  if (sel.has(id)) sel.delete(id); else sel.add(id);
  lvSave(lvSelKey(), JSON.stringify([...sel]));
  lvRenderHub();
}
function lvClearSel() {
  lvSel().clear();
  lvSave(lvSelKey(), '[]');
  lvRenderHub();
}

/* ─── Flashcard ─────────────────────────────────────────────────────────── */
function lvStartFlash(list) {
  tsStop();
  let deck = list || lvPool();
  let note = '';
  if (!list && _lvSkipKnown) {
    const k = lvKnownSet();
    const rest = deck.filter(w => !k.has(w.en.toLowerCase()));
    if (rest.length) deck = rest;
    else note = 'Đã nhớ hết các từ này, lượt này ôn lại cả bộ.';
  }
  if (!deck.length) return;
  _fc = { deck: vbShuffle(deck), i: 0, got: [], miss: [], flipped: false, retry: !!list };
  lvBindKeys();
  lvRenderFlash();
  if (note) showToast(note);
}

function lvRenderFlash() {
  const root = document.getElementById('lesson-vocab-root');
  if (!root || !_fc) return;
  const w = _fc.deck[_fc.i];
  const total = _fc.deck.length;
  const pct = Math.round(_fc.i / total * 100);
  const enFace = `<div class="lv-card-main">${escapeHtml(w.en)}</div>`;
  const viFace = `<div class="lv-card-main lv-card-main--vi">${escapeHtml(w.vi)}</div>`;
  const detail = `
    ${_lvFront === 'vi' ? enFace : viFace}
    ${w.use ? `<div class="lv-card-use">${escapeHtml(w.use)}</div>` : ''}
    ${w.ex ? `<div class="lv-card-ex">${escapeHtml(w.ex)}</div>` : ''}`;
  root.innerHTML = `
    <div class="lv-wrap lv-wrap--narrow">
      <div class="lv-fc-top">
        <button class="btn-back-plain" onclick="lvRenderHub()">← Chọn buổi</button>
        <button class="ts-icon-btn" onclick="lvModeModal()" title="Đổi chế độ" aria-label="Đổi chế độ">🔀</button>
        <div class="lv-fc-opts">
          <button class="vb-chip${_lvFront === 'en' ? ' active' : ''}" onclick="lvSetFront('en')">Mặt trước tiếng Anh</button>
          <button class="vb-chip${_lvFront === 'vi' ? ' active' : ''}" onclick="lvSetFront('vi')">Mặt trước tiếng Việt</button>
          ${_fc.retry ? '' : `<label class="lv-check"><input type="checkbox"${_lvSkipKnown ? ' checked' : ''} onchange="lvSetSkip(this.checked)"> Bỏ qua từ đã nhớ</label>`}
        </div>
      </div>
      <div class="lv-progress"><div class="lv-progress-bar" style="width:${pct}%"></div></div>
      <div class="lv-count">${_fc.i + 1} / ${total}</div>
      <div class="lv-card${_fc.flipped ? ' flipped' : ''}" onclick="lvFlip()">
        <div class="lv-card-inner">
          <div class="lv-face lv-face--front">
            <div class="lv-card-tag">${escapeHtml(w.tag || '')} · ${escapeHtml(w.group)}</div>
            ${_lvFront === 'vi' ? viFace : enFace}
            <div class="lv-card-hint">Bấm để lật</div>
          </div>
          <div class="lv-face lv-face--back">
            <div class="lv-card-tag">${escapeHtml(_lvFront === 'vi' ? w.vi : w.en)}</div>
            ${detail}
          </div>
        </div>
      </div>
      <div class="lv-fc-btns">
        <button class="lv-btn lv-btn--miss" onclick="lvMark(false)">✗ Chưa nhớ</button>
        <button class="lv-btn lv-btn--say" onclick="tsSpeak(${escapeHtml(JSON.stringify(w.en))})" title="Nghe" aria-label="Nghe">🔊</button>
        <button class="lv-btn lv-btn--got" onclick="lvMark(true)">✓ Nhớ rồi</button>
      </div>
      <div class="vb-hint-text">Phím cách để lật thẻ. Mũi tên trái là chưa nhớ, mũi tên phải là nhớ rồi.</div>
    </div>`;
}

function lvFlip() {
  if (!_fc) return;
  _fc.flipped = !_fc.flipped;
  const card = document.querySelector('#lesson-vocab-root .lv-card');
  if (card) card.classList.toggle('flipped', _fc.flipped);
}
function lvSetFront(side) { _lvFront = side; lvSave('lvFront', side); lvRenderFlash(); }
function lvSetSkip(on) { _lvSkipKnown = on; lvSave('lvSkipKnown', on ? '1' : '0'); lvStartFlash(); }

function lvMark(ok) {
  if (!_fc) return;
  const w = _fc.deck[_fc.i];
  const known = lvKnownSet();
  const k = w.en.toLowerCase();
  if (ok) { known.add(k); _fc.got.push(w); } else { known.delete(k); _fc.miss.push(w); }
  lvSaveKnown(known);
  _fc.i++;
  _fc.flipped = false;
  if (_fc.i >= _fc.deck.length) lvRenderFlashDone(); else lvRenderFlash();
}

function lvRenderFlashDone() {
  const root = document.getElementById('lesson-vocab-root');
  if (!root || !_fc) return;
  lvUnbindKeys();
  const miss = _fc.miss;
  _fc.done = true;
  root.innerHTML = `
    <div class="vb-wrap">
      <div class="vb-results">
        <div class="vb-results-score">${_fc.got.length}/${_fc.deck.length}</div>
        <div class="vb-results-score-lbl">từ đã nhớ trong lượt này</div>
        <div class="vb-missed">
          <div class="vb-missed-title">📒 Chưa nhớ</div>
          ${miss.length
            ? miss.map(w => `<div class="vb-missed-item"><strong>${escapeHtml(w.en)}</strong> · ${escapeHtml(w.vi)}</div>`).join('')
            : '<div class="vb-missed-empty">Nhớ hết cả lượt 🎉</div>'}
        </div>
        <div class="vb-results-btns">
          ${miss.length ? `<button class="vb-start-btn" onclick="lvStartFlash(_fc.miss.slice())">↺ Ôn lại ${miss.length} từ chưa nhớ</button>
          <button class="vb-secondary-btn" onclick="tsStart('meaning', _fc.miss.slice())">🎯 Bắn các từ này</button>` : ''}
          <button class="vb-secondary-btn" onclick="lvRenderHub()">← Chọn buổi</button>
        </div>
      </div>
    </div>`;
}

/* ─── Kiểm tra: a Quizlet-style test over the cards marked "Nhớ rồi" ─────── */
// One page of questions in up to four sections (true/false, multiple
// choice, written, matching), marked together at the end. Wrong answers can
// go straight back into Flashcard. Settings live in localStorage.
let _qt = null;
const QT_TYPES = [
  { id: 'tf', name: 'Đúng / Sai' },
  { id: 'mc', name: 'Trắc nghiệm' },
  { id: 'wr', name: 'Tự gõ từ' },
  { id: 'match', name: 'Nối từ' },
];
let _qtOpt = { n: 20, ans: 'en', types: ['tf', 'mc', 'wr', 'match'], all: false };
try { const o = JSON.parse(localStorage.getItem('qtOpt') || 'null'); if (o && Array.isArray(o.types)) _qtOpt = { ..._qtOpt, ...o }; } catch (e) {}

// The cards to test: the known ones in the current selection, or every card
// when the student asks for the whole set.
function qtDeck() {
  const pool = lvPool();
  if (_qtOpt.all) return pool;
  const k = lvKnownSet();
  return pool.filter(w => k.has(w.en.toLowerCase()));
}

function qtSetup() {
  lvLeaveGame();
  _qt = null;
  const root = document.getElementById('lesson-vocab-root');
  if (!root) return;
  const known = qtDeck();
  const pool = lvPool();
  const enough = known.length >= 4;
  const opt = (k, v, label) => `<button class="vb-chip${_qtOpt[k] === v ? ' active' : ''}" onclick="qtOpt('${k}', ${JSON.stringify(v).replace(/"/g, '&quot;')})">${label}</button>`;
  root.innerHTML = `
    <div class="lv-wrap lv-wrap--narrow">
      <div class="lv-fc-top">
        <button class="btn-back-plain" onclick="lvRenderHub()">← Chọn ${_lvSrc === 'unit' ? 'unit' : 'buổi'}</button>
        <button class="ts-icon-btn" onclick="lvModeModal()" title="Đổi chế độ" aria-label="Đổi chế độ">🔀</button>
      </div>
      <div class="qt-setup">
        <div class="vb-logo">📝 Kiểm tra</div>
        <div class="vb-tagline">Kiểm tra những thẻ em đã bấm <b>✓ Nhớ rồi</b> trong Flashcard. Làm hết rồi nộp một lần, như Quizlet.</div>
        <div class="qt-row"><span>Nguồn thẻ</span>
          ${opt('all', false, `Thẻ đã nhớ (${lvKnownCount(pool)})`)}${opt('all', true, `Cả bộ đang chọn (${pool.length})`)}</div>
        <div class="qt-row"><span>Số câu</span>
          ${[10, 20, 40].map(n => opt('n', n, n + ' câu')).join('')}${opt('n', 0, 'Tất cả')}</div>
        <div class="qt-row"><span>Trả lời bằng</span>
          ${opt('ans', 'en', 'Tiếng Anh')}${opt('ans', 'vi', 'Tiếng Việt')}${opt('ans', 'mix', 'Trộn cả hai')}</div>
        <div class="qt-row"><span>Dạng câu hỏi</span>
          ${QT_TYPES.map(t => `<button class="vb-chip${_qtOpt.types.includes(t.id) ? ' active' : ''}" onclick="qtType('${t.id}')">${t.name}</button>`).join('')}</div>
        ${enough
          ? `<button class="vb-start-btn qt-go" onclick="qtStart()">Bắt đầu · ${Math.min(known.length, _qtOpt.n || known.length)} câu</button>`
          : `<div class="qt-empty">Mới có ${known.length} thẻ đã nhớ trong phần đang chọn. Cần ít nhất 4 thẻ.<br>
              <button class="vb-start-btn" onclick="lvStartFlash()">🃏 Học Flashcard trước</button>
              <button class="vb-secondary-btn" onclick="qtOpt('all', true)">Kiểm tra cả bộ</button></div>`}
      </div>
    </div>`;
}
function lvKnownCount(pool) { const k = lvKnownSet(); return pool.filter(w => k.has(w.en.toLowerCase())).length; }
function qtOpt(k, v) { _qtOpt[k] = v; lvSave('qtOpt', JSON.stringify(_qtOpt)); tsSfx('key'); qtSetup(); }
function qtType(id) {
  const t = _qtOpt.types;
  if (t.includes(id)) { if (t.length > 1) t.splice(t.indexOf(id), 1); } else t.push(id);
  lvSave('qtOpt', JSON.stringify(_qtOpt));
  tsSfx('key');
  qtSetup();
}

// Builds the paper. Cards are shared out across the chosen sections in
// order; matching takes groups of up to five.
function qtStart(list) {
  const deck = vbShuffle((list || qtDeck()).slice());
  const n = list ? deck.length : Math.min(deck.length, _qtOpt.n || deck.length);
  const cards = deck.slice(0, n);
  if (cards.length < 1) return;
  const distract = lvPool();
  const types = _qtOpt.types.slice().sort((a, b) => QT_TYPES.findIndex(t => t.id === a) - QT_TYPES.findIndex(t => t.id === b));
  const per = Math.ceil(cards.length / types.length);
  const qs = [];
  let at = 0;
  types.forEach(type => {
    const part = cards.slice(at, at + per);
    at += per;
    if (type === 'match') {
      for (let i = 0; i < part.length; i += 5) {
        const g = part.slice(i, i + 5);
        if (g.length < 2) { g.forEach(w => qs.push(qtQuestion('mc', w, distract))); continue; }
        qs.push({ type: 'match', cards: g, order: vbShuffle(g.map((_, j) => j)), pick: g.map(() => ''), ask: qtAsk() });
      }
    } else part.forEach(w => qs.push(qtQuestion(type, w, distract)));
  });
  _qt = { qs, list: cards, done: false };
  qtRender();
  window.scrollTo(0, 0);
}
// Which side the student answers in: 'en' means the prompt is Vietnamese.
function qtAsk() { return _qtOpt.ans === 'mix' ? (Math.random() < 0.5 ? 'en' : 'vi') : _qtOpt.ans; }
function qtOthers(w, pool, n) {
  const same = pool.filter(x => x.en !== w.en && x.vi !== w.vi && x.group === w.group);
  const rest = pool.filter(x => x.en !== w.en && x.vi !== w.vi && x.group !== w.group);
  return [...vbShuffle(same), ...vbShuffle(rest)].slice(0, n);
}
function qtQuestion(type, w, pool) {
  const ask = type === 'wr' ? 'en' : qtAsk();
  const q = { type, w, ask, pick: null };
  if (type === 'mc') q.opts = vbShuffle([w, ...qtOthers(w, pool, 3)]);
  if (type === 'tf') { q.truth = Math.random() < 0.5; q.shown = q.truth ? w : (qtOthers(w, pool, 1)[0] || w); if (q.shown === w) q.truth = true; }
  return q;
}
const qtSide = (w, side) => (side === 'en' ? w.en : w.vi);

function qtRender() {
  const root = document.getElementById('lesson-vocab-root');
  if (!root || !_qt) return;
  const g = _qt;
  const answered = g.qs.filter(qtAnswered).length;
  const body = g.qs.map((q, i) => qtRenderQ(q, i)).join('');
  root.innerHTML = `
    <div class="lv-wrap lv-wrap--narrow qt-wrap">
      <div class="lv-fc-top">
        <button class="btn-back-plain" onclick="qtSetup()">← Cài đặt</button>
        <button class="ts-icon-btn" onclick="lvModeModal()" title="Đổi chế độ" aria-label="Đổi chế độ">🔀</button>
      </div>
      ${g.done ? qtScoreCard() : `<div class="qt-bar"><span>📝 ${g.qs.length} câu · đã làm <b id="qt-count">${answered}</b></span></div>`}
      <div class="qt-list">${body}</div>
      ${g.done ? qtAfterBtns() : `<button class="vb-start-btn qt-submit" onclick="qtSubmit()">Nộp bài</button>`}
    </div>`;
}
function qtAnswered(q) {
  if (q.type === 'match') return q.pick.every(Boolean);
  if (q.type === 'wr') return !!(q.pick && q.pick.trim());
  return q.pick !== null;
}
function qtHead(q, i, label) {
  const mark = !_qt.done ? '' : q.ok ? '<span class="qt-ok">✓ Đúng</span>' : '<span class="qt-bad">✗ Sai</span>';
  return `<div class="qt-qhead"><span>${i + 1}. ${label}</span>${mark}</div>`;
}
function qtRenderQ(q, i) {
  const done = _qt.done;
  const other = q.ask === 'en' ? 'vi' : 'en';
  const cls = `qt-q${done ? (q.ok ? ' qt-q--ok' : ' qt-q--bad') : ''}`;
  if (q.type === 'tf') {
    return `<div class="${cls}">${qtHead(q, i, 'Đúng hay sai?')}
      <div class="qt-pair"><b>${escapeHtml(qtSide(q.w, other))}</b><span>=</span><span>${escapeHtml(qtSide(q.shown, q.ask))}</span></div>
      <div class="qt-opts qt-opts--2">${[true, false].map(v => `<button class="qt-opt${q.pick === v ? ' on' : ''}${done && v === q.truth ? ' right' : ''}" onclick="qtPick(${i}, ${v})" ${done ? 'disabled' : ''}>${v ? 'Đúng' : 'Sai'}</button>`).join('')}</div>
      ${done && !q.ok ? `<div class="qt-fix">Đáp án: <b>${escapeHtml(q.w.en)}</b> = ${escapeHtml(q.w.vi)}</div>` : ''}</div>`;
  }
  if (q.type === 'mc') {
    return `<div class="${cls}">${qtHead(q, i, 'Chọn đáp án đúng')}
      <div class="qt-prompt">${escapeHtml(qtSide(q.w, other))}</div>
      <div class="qt-opts">${q.opts.map((o, j) => `<button class="qt-opt${q.pick === j ? ' on' : ''}${done && o === q.w ? ' right' : ''}" onclick="qtPick(${i}, ${j})" ${done ? 'disabled' : ''}>${escapeHtml(qtSide(o, q.ask))}</button>`).join('')}</div></div>`;
  }
  if (q.type === 'wr') {
    return `<div class="${cls}">${qtHead(q, i, 'Gõ từ tiếng Anh')}
      <div class="qt-prompt">${escapeHtml(q.w.vi)}</div>
      <input class="ts-input qt-input" type="text" autocomplete="off" autocapitalize="none" spellcheck="false" value="${escapeHtml(q.pick || '')}" oninput="qtType2(${i}, this.value)" ${done ? 'disabled' : ''} placeholder="Gõ từ tiếng Anh">
      ${done && !q.ok ? `<div class="qt-fix">Đáp án: <b>${escapeHtml(q.w.en)}</b></div>` : done && q.near ? '<div class="qt-fix">Gần đúng, sai một chữ cái.</div>' : ''}</div>`;
  }
  // Matching: prompts on the left, lettered answers on the right.
  const letters = 'ABCDE';
  const other2 = q.ask === 'en' ? 'vi' : 'en';
  return `<div class="${cls}">${qtHead(q, i, 'Nối mỗi dòng với đáp án')}
    <div class="qt-match">
      <div>${q.cards.map((c, j) => {
        const right = done && q.pick[j] === letters[q.order.indexOf(j)];
        return `<div class="qt-mrow"><select onchange="qtMatch(${i}, ${j}, this.value)" ${done ? 'disabled' : ''} class="${done ? (right ? 'right' : 'wrong') : ''}"><option value="">?</option>${q.cards.map((_, k) => `<option${q.pick[j] === letters[k] ? ' selected' : ''}>${letters[k]}</option>`).join('')}</select><span>${escapeHtml(qtSide(c, other2))}</span>${done && !right ? `<small>→ ${letters[q.order.indexOf(j)]}</small>` : ''}</div>`;
      }).join('')}</div>
      <div>${q.order.map((j, k) => `<div class="qt-mans"><b>${letters[k]}</b> ${escapeHtml(qtSide(q.cards[j], q.ask))}</div>`).join('')}</div>
    </div></div>`;
}
function qtPick(i, v) {
  if (!_qt || _qt.done) return;
  _qt.qs[i].pick = v;
  tsSfx('key');
  const y = window.scrollY;
  qtRender();
  window.scrollTo(0, y);
}
function qtType2(i, v) {
  if (!_qt || _qt.done) return;
  _qt.qs[i].pick = v;
  const c = document.getElementById('qt-count');
  if (c) c.textContent = _qt.qs.filter(qtAnswered).length;
}
function qtMatch(i, j, v) {
  if (!_qt || _qt.done) return;
  _qt.qs[i].pick[j] = v;
  const c = document.getElementById('qt-count');
  if (c) c.textContent = _qt.qs.filter(qtAnswered).length;
}
// "work-life balance / balance" style answers: any listed form counts, and
// words in brackets are optional.
function qtForms(en) {
  return String(en).split('/').map(s => raidNorm(s.replace(/\(.*?\)/g, ' '))).filter(Boolean);
}
function qtSubmit() {
  const g = _qt;
  if (!g || g.done) return;
  const left = g.qs.filter(q => !qtAnswered(q)).length;
  if (left && !confirm(`Còn ${left} câu chưa làm. Vẫn nộp bài?`)) return;
  const letters = 'ABCDE';
  g.wrong = [];
  let right = 0, total = 0;
  g.qs.forEach(q => {
    if (q.type === 'match') {
      const oks = q.cards.map((c, j) => q.pick[j] === letters[q.order.indexOf(j)]);
      oks.forEach((ok, j) => { total++; if (ok) right++; else g.wrong.push(q.cards[j]); });
      q.ok = oks.every(Boolean);
      return;
    }
    total++;
    if (q.type === 'tf') q.ok = q.pick === q.truth;
    else if (q.type === 'mc') q.ok = q.pick !== null && q.opts[q.pick] === q.w;
    else {
      const typed = raidNorm(q.pick || '');
      const forms = qtForms(q.w.en);
      q.ok = forms.includes(typed);
      if (!q.ok && typed && forms.some(f => raidNear(f, typed))) { q.ok = true; q.near = true; }
    }
    if (q.ok) right++; else g.wrong.push(q.w);
  });
  g.right = right; g.total = total; g.done = true;
  g.wrong = [...new Set(g.wrong)];
  lvLogTest(g);
  questBump('vocab_test', 1);
  const coins = Math.round(right * walMult());
  g.coins = coins;
  if (coins) walEarn(coins, true);
  tsSfx(right === total ? 'rankup' : 'level');
  if (right === total) jConfetti(90);
  qtRender();
  window.scrollTo(0, 0);
}
function qtScoreCard() {
  const g = _qt;
  const pct = Math.round(g.right / g.total * 100);
  const msg = pct === 100 ? 'Tuyệt đối! 🎉' : pct >= 80 ? 'Rất tốt, ôn nốt vài từ sai là chắc.' : pct >= 50 ? 'Ổn. Ôn lại các từ sai rồi làm lại nhé.' : 'Cần ôn thêm. Học lại Flashcard các từ sai trước.';
  return `<div class="qt-score">
    <div class="qt-ring" style="--p:${pct}"><span>${pct}%</span></div>
    <div><div class="qt-score-n">${g.right} / ${g.total} đúng</div><div class="qt-score-msg">${msg}</div>${g.coins ? `<div class="qt-score-coin">+${g.coins} 🪙</div>` : ''}</div>
  </div>`;
}
function qtAfterBtns() {
  const w = _qt.wrong.length;
  return `<div class="vb-results-btns qt-after">
    ${w ? `<button class="vb-start-btn" onclick="qtStart(_qt.wrong.slice())">↺ Kiểm tra lại ${w} từ sai</button>
    <button class="vb-secondary-btn" onclick="qtRelearn()">🃏 Học lại ${w} từ sai</button>` : ''}
    <button class="vb-secondary-btn" onclick="qtStart()">📝 Làm bài mới</button>
    <button class="vb-secondary-btn" onclick="lvRenderHub()">← Chọn ${_lvSrc === 'unit' ? 'unit' : 'buổi'}</button>
  </div>`;
}
// Wrong answers lose their "Nhớ rồi" mark, so Flashcard shows them again.
function qtRelearn() {
  const list = _qt.wrong.slice();
  const k = lvKnownSet();
  list.forEach(w => k.delete(w.en.toLowerCase()));
  lvSaveKnown(k);
  lvStartFlash(list);
}

/* ─── Tiến độ từ vựng: per topic, per set, and the Kiểm tra history ───────
   One renderer for the student's own page and for the teacher's view of any
   student, fed a known set and a list of tests. */
const lvPct = (k, n) => (n ? Math.round(k / n * 100) : 0);
function lvBar(k, n, thin) {
  const p = lvPct(k, n);
  const tone = p >= 80 ? 'hi' : p >= 40 ? 'mid' : 'lo';
  return `<span class="lvp-bar${thin ? ' lvp-bar--thin' : ''}"><i class="lvp-bar-${tone}" style="width:${p}%"></i></span>`;
}
// Words shared by two topics count once in a set's total.
function lvSetCount(topics, known) {
  const all = new Set();
  topics.forEach(t => t.items.forEach(w => all.add(w.en.toLowerCase())));
  let k = 0;
  all.forEach(w => { if (known.has(w)) k++; });
  return { k, n: all.size };
}
function lvProgSets() {
  return [
    { id: 'basic', icon: '🌱', label: 'Cơ bản · 25 unit', topics: lvTopics('unit', 'basic') },
    { id: 'adv', icon: '🚀', label: 'Nâng cao · 25 unit', topics: lvTopics('unit', 'adv') },
    { id: 'lesson', icon: '📘', label: LESSON_VOCAB.length + ' buổi Writing', topics: lvTopics('lesson') },
  ];
}
function lvTestLabel(t) {
  const set = t.src === 'lesson' ? '📘 Buổi' : t.tier === 'adv' ? '🚀 Nâng cao' : '🌱 Cơ bản';
  const tops = (t.topics || []).length ? (t.src === 'lesson' ? 'buổi ' : 'unit ') + t.topics.join(', ') : 'tất cả';
  return `${set} · ${tops}`;
}
const lvWhen = iso => { try { return new Date(iso).toLocaleString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }); } catch (e) { return ''; } };
function lvProgressHTML(known, tests) {
  const sets = lvProgSets();
  const tsts = (tests || []).slice().reverse();
  const avg = tsts.length ? Math.round(tsts.reduce((s, t) => s + lvPct(t.right, t.total), 0) / tsts.length) : 0;
  const best = tsts.reduce((b, t) => Math.max(b, lvPct(t.right, t.total)), 0);
  const cards = sets.map(s => {
    const c = lvSetCount(s.topics, known);
    const rows = s.topics.filter(t => t.items.length).map(t => {
      const k = t.items.filter(w => known.has(w.en.toLowerCase())).length;
      return `<div class="lvp-row"><span class="lvp-row-name"><b>${escapeHtml(t.label)}</b> ${escapeHtml(t.title)}</span>${lvBar(k, t.items.length, true)}<span class="lvp-row-n">${k}/${t.items.length}</span></div>`;
    }).join('');
    return `<details class="lvp-set">
      <summary><span class="lvp-set-top"><strong>${s.icon} ${escapeHtml(s.label)}</strong><span>${c.k}/${c.n} · ${lvPct(c.k, c.n)}%</span></span>${lvBar(c.k, c.n)}<span class="lvp-more">Xem từng chủ đề</span></summary>
      <div class="lvp-rows">${rows}</div>
    </details>`;
  }).join('');
  const hist = tsts.length ? tsts.slice(0, 50).map(t => {
    const p = lvPct(t.right, t.total);
    return `<div class="lvp-test">
      <div class="lvp-test-top"><span class="lvp-test-when">${lvWhen(t.at)}</span><span class="lvp-test-score">${t.right}/${t.total} · ${p}%</span></div>
      <div class="lvp-test-what">${escapeHtml(lvTestLabel(t))}</div>
      ${lvBar(t.right, t.total, true)}
      ${(t.wrong || []).length ? `<div class="lvp-test-wrong">Sai: ${t.wrong.map(w => escapeHtml(w)).join(', ')}</div>` : ''}
    </div>`;
  }).join('') : '<div class="lvp-empty">Chưa làm bài Kiểm tra nào.</div>';
  return `<div class="lvp">
    <div class="lvp-sum">
      <div><b>${known.size}</b><span>thẻ đã nhớ</span></div>
      <div><b>${tsts.length}</b><span>bài kiểm tra</span></div>
      <div><b>${tsts.length ? avg + '%' : '–'}</b><span>điểm trung bình</span></div>
      <div><b>${tsts.length ? best + '%' : '–'}</b><span>cao nhất</span></div>
    </div>
    <div class="lvp-sets">${cards}</div>
    <h3 class="lvp-h">📝 Lịch sử kiểm tra</h3>
    <div class="lvp-hist">${hist}</div>
  </div>`;
}
async function lvShowProgress() {
  lvLeaveGame();
  const root = document.getElementById('lesson-vocab-root');
  if (!root) return;
  root.innerHTML = '<div class="loading">Đang tải tiến độ…</div>';
  const p = await lvLoadProgress();
  try { await ensureVocabBank(); } catch (e) {}
  if (!document.getElementById('lesson-vocab-root')) return;
  root.innerHTML = `<div class="lv-wrap">
    <button class="btn-back-plain" onclick="lvRenderHub()">← Về Flashcard và Bắn Chữ</button>
    <div class="vb-logo">📊 Tiến độ từ vựng của em</div>
    ${p.loaded ? '' : '<div class="lvp-empty">Chưa tải được dữ liệu từ máy chủ, đang hiện bản lưu trên máy này.</div>'}
    ${lvProgressHTML(p.known, p.tests)}
  </div>`;
  window.scrollTo(0, 0);
}
function lvLogTest(g) {
  const t = {
    at: new Date().toISOString(),
    src: _lvSrc,
    tier: _lvTier,
    topics: [...lvSel()].sort((x, y) => x - y),
    right: g.right,
    total: g.total,
    wrong: g.wrong.map(w => w.en.toLowerCase()),
  };
  const p = lvProgFor();
  p.tests = [...p.tests, t].slice(-100);
  api('/api/vocab/progress/test', { method: 'POST', body: JSON.stringify(t) }).catch(() => {});
}

/* Teacher: every student of the class, one row each, open a row for the
   same page the student sees. */
let _cvRows = [];
async function loadClassVocab() {
  const el = document.getElementById('class-vocab-content');
  el.innerHTML = '<div class="loading">Đang tải tiến độ từ vựng…</div>';
  try {
    const [rows] = await Promise.all([api(`/api/vocab/progress/class/${currentClassId}`), ensureVocabBank()]);
    _cvRows = rows;
    if (!rows.length) { el.innerHTML = '<div class="empty-state">Lớp chưa có học sinh.</div>'; return; }
    const sets = lvProgSets();
    const last = r => [r.updated_at, ...(r.tests || []).map(t => t.at)].filter(Boolean).sort().pop();
    el.innerHTML = `<div class="cv-note">Bấm vào tên học sinh để xem từng chủ đề và lịch sử kiểm tra.</div>
      <div class="cv-list">${rows.map((r, i) => {
        const known = new Set(r.known || []);
        const tests = r.tests || [];
        const avg = tests.length ? Math.round(tests.reduce((s, t) => s + lvPct(t.right, t.total), 0) / tests.length) : null;
        const l = last(r);
        const t1 = [...Object.values((r.t1 || {}).dyn || {}), ...Object.values((r.t1 || {}).sta || {})];
        return `<div class="cv-row" id="cv-row-${i}">
          <button class="cv-head" onclick="cvToggle(${i})">
            <span class="cv-name">${escapeHtml(r.name)}</span>
            <span class="cv-meta">${tests.length} bài KT${avg !== null ? ` · TB ${avg}%` : ''} · ${l ? 'hoạt động ' + lvWhen(l) : 'chưa học'}${t1.length ? ` · Task 1 thuộc ${t1.filter(v => v.m >= 3).length}/${t1.length} cụm` : ''}</span>
            <span class="cv-bars">${sets.map(s => { const c = lvSetCount(s.topics, known); return `<span class="cv-bar"><small>${s.icon} ${lvPct(c.k, c.n)}%</small>${lvBar(c.k, c.n, true)}</span>`; }).join('')}</span>
          </button>
          <div class="cv-detail hidden" id="cv-detail-${i}"></div>
        </div>`;
      }).join('')}</div>`;
  } catch (err) {
    el.innerHTML = `<div class="error-msg" style="display:block">${escapeHtml(err.message)}</div>`;
  }
}
function cvToggle(i) {
  const d = document.getElementById('cv-detail-' + i);
  if (!d) return;
  const open = d.classList.toggle('hidden') === false;
  if (open && !d.innerHTML) { const r = _cvRows[i]; d.innerHTML = lvProgressHTML(new Set(r.known || []), r.tests || []) + cvT1HTML(r.t1); }
}
// Task 1 phrases from Sinh tồn: how many are known, and the weakest ones.
function cvT1HTML(t1) {
  const rows = [];
  [['dyn', 'Biểu đồ động'], ['sta', 'Biểu đồ tĩnh']].forEach(([b, name]) => Object.entries((t1 || {})[b] || {}).forEach(([k, v]) => rows.push({ k, b: name, m: v.m || 0, w: v.w || 0 })));
  if (!rows.length) return '';
  const weak = rows.filter(r => r.m <= 2).sort((a, b) => a.m - b.m || b.w - a.w).slice(0, 15);
  return `<div class="cv-t1"><div class="cv-t1-h">🛡️ Task 1 · Sinh tồn: ${rows.filter(r => r.m >= 3).length}/${rows.length} cụm đã thuộc (độ thuộc 3–4 trên 4)</div>
    ${weak.length ? `<table class="cv-t1-t"><tr><th>Cụm còn yếu</th><th>Khối</th><th>Độ thuộc</th><th>Số lần sai</th></tr>${weak.map(r => `<tr><td>${escapeHtml(r.k)}</td><td>${r.b}</td><td>${r.m}/4</td><td>${r.w}</td></tr>`).join('')}</table>` : '<p>Không còn cụm yếu.</p>'}</div>`;
}

function lvBindKeys() {
  lvUnbindKeys();
  _fcKeyHandler = e => {
    const view = document.getElementById('view-lesson-vocab');
    if (!view || view.classList.contains('hidden') || !_fc || _fc.done) { lvUnbindKeys(); return; }
    if (e.target.closest && e.target.closest('input, textarea, select')) return;
    if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); lvFlip(); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); lvMark(false); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); lvMark(true); }
  };
  document.addEventListener('keydown', _fcKeyHandler);
}
function lvUnbindKeys() {
  if (_fcKeyHandler) document.removeEventListener('keydown', _fcKeyHandler);
  _fcKeyHandler = null;
  twStop();
  raidStop();
}

