  if (k === 'burn') { heal(dmg); raidSparkle('rd-hero', '🩸', 5); }
  if (k === 'holy') { heal(15); g.mana = Math.min(100, g.mana + 20); raidSparkle('rd-hero', '🙏', 5); }
  raidRenderBars();
