  n: { name: 'Số liệu', color: '#14864A' },
  t: { name: 'Thời gian', color: '#8E44AD' },
  p: { name: 'Nơi chốn / nhóm', color: '#0E8C96' },
  o: { name: 'Đối tượng', color: '#C2571A' },
