function ttmTileAt(x, y) { return (TTM_MAP[y] || '')[x] || 'T'; }
function ttmBuildAt(x, y) { return TTM_BUILD.find(b => x >= b.x && x < b.x + b.t[0].length && y >= b.y && y < b.y + b.t.length); }
