    mast: s ? s.mast || {} : {}, fled: s ? s.fled || {} : {}, badge: s ? !!s.badge : false, trainerWon: s ? !!s.trainerWon : false,
    p: { x: s ? s.x : 13, y: s ? s.y : 19, fx: 0, fy: 0, face: 1, dir: 'u', moving: false, t: 0, anim: 0 },
